import { randomBytes } from 'node:crypto';
import { mkdirSync, writeFileSync } from 'node:fs';

const targetDirectory = 'supabase/functions';
const targetPath = `${targetDirectory}/.env`;

mkdirSync(targetDirectory, { recursive: true });
writeFileSync(
  targetPath,
  [
    '# Generated by npm run db:edge-env. Never use these settings publicly.',
    'PROJECT_S_ENVIRONMENT=development',
    'PROJECT_S_PUBLIC_APP_URL=http://127.0.0.1:8080',
    'PROJECT_S_ALLOWED_ORIGINS=http://127.0.0.1:8080,http://localhost:8080,http://127.0.0.1:4173,http://localhost:4173,http://127.0.0.1:4184,http://localhost:4184',
    `PROJECT_S_RATE_LIMIT_HMAC_SECRET=${randomBytes(32).toString('hex')}`,
    'PROJECT_S_TRUST_PROXY_HEADERS=false',
    'PROJECT_S_CHALLENGE_PROVIDER=development',
    '',
  ].join('\n'),
  { encoding: 'utf8', mode: 0o600 },
);

console.log('Wrote ignored local-only Edge Function configuration.');
